mapper.select:
SELECT * FROM agent_memories
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND forgotten_at IS NULL
ORDER BY kind ASC, updated_at DESC, id DESC

SELECT * FROM agent_memories
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND forgotten_at IS NOT NULL
ORDER BY forgotten_at DESC, id DESC
LIMIT #{limit}

SELECT * FROM agent_memories
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND id = #{id}

mapper.update:
UPDATE agent_memories
SET kind = #{kind},
    content = #{content},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND organization_id = #{organizationId}
  AND user_id = #{userId}
  AND forgotten_at IS NULL

UPDATE agent_memories
SET forgotten_at = #{forgottenAt},
    updated_at = #{forgottenAt}
WHERE id = #{id}
  AND organization_id = #{organizationId}
  AND user_id = #{userId}
  AND forgotten_at IS NULL
